# CIT 1 Gen feature tour
# Run with `cit main.cit` or the CIT Run command in VS Code.

import { math, ui }
import pi from math
import json
import time
import ui-style

# Variables, shared initialization, destructuring, and read lifetimes
let mut name = "Coder"
let mut first, second, third = 2
let mut num1 = 2
let mut num2 = num1: 4
let mut numbers = [10, 20, 30]
let mut [low, , high] = numbers
let mut [left, middle, right] = numbers
let mut shortLived <2r> = 7
println(name, first, second, third)
println(num2)
println(low, high, left, middle, right, shortLived)

# Temporal modes: offline resets its timer after access; stopUse observes VS Code inactivity.
let mut offlineValue <5s = offline> = 3
let mut inactiveValue <5s = stopUse> = 4
let mut lineScoped <30l> = "available for 30 source lines"

# Heterogeneous collections, constructors, slices, and set operations
let mut mixed = list(1, "two", true)
let point = tuple(1, "north", true)
let mut unique = set(1, 2, 2, 3)
let info = dict(num1: 1, num2: "two")
let fixedInfo = frozendict(num1: 2, num2: 3)
let frozenValues = frozenset(1, 2, 2, 3)
let otherValues = {2, 4}
let excludedValues = {1}
let changedValues = {2, 8}
println(mixed, point, unique, info, fixedInfo, frozenValues)
println(numbers[1:4], numbers[::-1], point.count(1), point.index("north"))
unique.add(4)
unique.update([4, 5])
println(union(unique, otherValues), intersection(unique, otherValues))
println(difference(unique, excludedValues), symmetricDifference(unique, changedValues))

# String, list, tuple, and numeric helpers
let greeting = "  cit 1 gen  "
println(greeting.trim().capitalize(), "CIT".isNumeric(), mixed.flat(), [1, 2, 3, 4].chunk(2))
println(math.ceil(3.1), math.floor(3.9), math.trunc(3.9), math.sqrt(16), math.cbrt(27))
println(math.exp(1), math.log(100, 10), math.log2(8), math.sin(math.pi / 2), math.cos(0), math.tan(0))
println(math.degrees(math.pi), math.radians(180), math.factorial(5), math.gcd(12, 18), math.lcm(12, 18))
println(math.e, math.pi, math.tau, math.nan, math.inf)

# Fixed-width storage and long conversions
int small: i16 = 16
float precise: f32 = 16.92
str label: s16 = "CIT"
bool enabled: b8 = true
let largeText = longString("A string value")
let largeNumber = longNumber("1234567.89")
println(small, precise, label, enabled, largeText, largeNumber)
println($"{math.pi:.2f}")

# from-import and bulk imports
println(pi, square(4))

# Functions, decorators, and higher-order built-ins
let logger = fn logger(original) {
    return argument => {
        println("Calling decorated function")
        return original(argument)
    }
}

@logger
fn greet(personName) {
    return $"Hello, {personName}!"
}

println(greet(name))
println(enumerate(["red", "blue"]), zip(["a", "b"], [1, 2]))
println(round(3.14159, 2), bin(12), square(5), id(name))
println(type(object()), enumarate(["first", "second"]))

# Errors, guards, enums, constants, and conditional expressions
const yearGrade = "A"
let enum colors = (["red", "yellow", "blue", "green"])
println(colors.red, "Pass" if (yearGrade == "A" || "B" || "C") else "Try again")
let state = if (enabled) {"Enabled"} else {"Disabled"}
println(state)

fn processUser(user) {
    guard (user != null) else {
        return "Invalid user"
    }
    return $"Bank: {user.bank}"
}

try {
    raise ValueError("Example validation error")
} except ValueError as err {
    println(err)
} finally {
    println("Validation finished")
}

# Classes, encapsulation, inheritance, and polymorphism
class Account() {
    fn struct(bank, pin, balance) {
        self.bank = bank
        private self.pin = pin
        protected self.balance = balance
    }

    fn showCreditCardInfo() {
        println(self.bank, self.pin, self.balance)
    }

    get fn credit() {
        return self.balance
    }

    set fn credit(value) {
        if (value >= 0) {
            self.balance = value
        }
    }
}

class Animal() {
    fn struct(animalName) {
        self.name = animalName
    }

    fn make_sound() {
        println($"{self.name} makes a generic sound.")
    }
}

class Dog(Animal()) {
    fn struct(animalName) {
        super().struct(animalName)
    }

    fn make_sound() {
        println($"{self.name} barks: Woof!")
    }
}

class Cat(Animal()) {
    fn struct(animalName) {
        super().struct(animalName)
    }

    fn make_sound() {
        println($"{self.name} meows: Meow!")
    }
}

final class Device() {
    fn struct(model) {
        self.model = model
    }
}

let mut account = Account("Chase", 1234, 12.34)
account.showCreditCardInfo()
account.credit = 20
println(account.credit, processUser(account))
let mut device = Device("CIT-1")
println(device.model)

fn introduceAnimal(animal) {
    animal.make_sound()
}

let mut dog = Dog("Rex")
let mut cat = Cat("Whiskers")
println(type(point), isinstance(small, "int"), issubclass(Dog, Animal))
introduceAnimal(dog)
introduceAnimal(cat)

# Loops, placeholders, and static local values
for (let mut index, range(0, 3)) {
    println(index)
}

for (_, range(0, 2)) {
    println("This loop does not bind its range value")
}

for (item in [1, 2, 3]) {
    println(item)
} else {
    println("The loop completed without break")
}

fn nextId() {
    static let mut current = 0
    current += 1
    return current
}
println(nextId(), nextId())

# JSON, time, colors, and UI
let jsonText = json.dumps({name: "CIT", version: 1}, indent = 2, sortKeys = true)
println(json.loads(jsonText)["name"])
println(time.strftime("%Y-%m-%d", time.localtime()))
println(time.time() > 0, time.ctime(0), time.perfCounter() > 0)
println(time.asctime(time.gmtime(0)), time.strftime("%Y-%m-%d", time.strptime("1970-01-01", "%Y-%m-%d")))
println(hex("336699"), rgb(51, 102, 153), hsl(210, 50, 40))

fn app(ui.title = "CIT 1 Gen") {
    style.connect("My Styler")
    return [
        ui.h1("Hello World!"),
        ui.p("A simple HTML-style preview."),
        ui.button("Continue", class = "primary"),
        ui.input(type = "email", required = true, min = 12, max = 24)
    ]
}

fn styling(style.title = "My Styler") {
    let background = "#f4f4f4"
    return [
        body {
            backgroundColor = background
            textColor = "#222222"
        },
        button {
            backgroundColor = "#336699"
            textColor = "#ffffff"
        }
    ]
}

app().render()

# Additional supported tools:
printf("My name is %s; I code in %s.\n", name, "CIT")
let oldValue = exchange(first, 20)
println(first, oldValue)
task.wait(0.01)

fn saveNotes() {
    with open("notes.txt", "write", encoding = "utf-8") as file {
        file.write("First line.\n")
        file.write("Second line.\n")
    }
    with open("notes.txt", "append", encoding = "utf-8") as file {
        file.write("Last line.\n")
    }
}

fn showDialogs() {
    let response = window.prompt("What is your name?")
    window.alert($"Hello, {response}!")
}

# final class Example() {} cannot be subclassed.
